g=[r+[9]*(29-len(r)) for r in g]
for i in range(7):
    top={j for j,v in enumerate(g[i]) if v==8}
    bot={j for j,v in enumerate(g[i+20]) if v==8}
    exp={j+2 for j in top if j+2<29}
    print(i,'src',sorted(top),'exp',sorted(exp),'bot',sorted(bot),'miss',sorted(exp-bot),'extra',sorted(bot-exp))
